(() => {
 const data=window.LISTENING_POINTERS;
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function render(scope,id,language){
  const lang=language==='he'?'he':'en',points=data[scope]?.[id];
  if(!Array.isArray(points)||points.length<2||points.length>4)return '';
  const summary=lang==='he'?'נקודות להקשבה ולמחשבה':'Pointers for listening and thinking';
  const note=lang==='he'?'כיוונים לבדיקה, לא תשובה יחידה. אפשר להקשיב קודם ולפתוח אחר כך.':'Ideas to test, not a single answer. Listen first if you like, then open these.';
  return `<details class="listening-pointers" data-listening-pointers="${esc(scope+':'+id)}"><summary>${summary}</summary><p class="listening-pointers-note">${note}</p><ul>${points.map(point=>`<li>${esc(point[lang])}</li>`).join('')}</ul></details>`;
 }
 function gallery(group,item,lang){return render('items',item?.id,lang)||render('groups',group?.id,lang)}
 window.ListeningPointers={render,gallery};
})();
